        && !std::strcmp(l.SubMeshCloth->type, l.PrimitiveCloth->type) && l.Helpers->subs[1] == l.Dummy && !std::strcmp(l.Root->type, "3DRT");
    std::printf(ok ? "00a9bbe0_TEST PASS\n" : "00a9bbe0_TEST FAIL\n");
    return ok ? 0 : 1;
}

